\section{The level-six lattice}\label{sec:s6}

\begin{calculation}[Engel's fibre lattice]
For Engel's based rank-four fibre lattice $\Lambda$ with invariant alternating form $\xi$, fibre class $\delta$ and primitive fibre character $\psi$, in the convention $\iota_\delta\xi(v)=\xi(\delta,v)$: $\iota_\delta\xi=-6\psi$, so $\ker\psi=\delta^{\perp_\xi}$, $\Lambda_{\mathrm{red}}=\ker\psi/\Z\delta$ has rank two with a unimodular induced form; $\xi^\flat:\Lambda\to\Lambda^*$ has Smith invariants $1,1,6,6$ (Pfaffian $-6$, determinant $36$), $D_\xi=\operatorname{coker}\xi^\flat\cong(\Z/6)^2$, and the finite Heisenberg group of $D_\xi$ with primitive central character has an explicit irreducible six-dimensional representation. For $G(r,s;m,n)=\langle c,x_0,x_1\mid c\text{ central},\ x_0x_1=1,\ x_0^r=c^m,\ x_1^s=c^n\rangle$ and $D=rn+sm\ne0$: $G\cong\Z/d_1\oplus\Z/d_2$ with $d_1=\gcd(r,s,m,n)$, $d_1d_2=|D|$ (with a global-section integer $b$ the determinant is $rn+sm-rsb$). In Engel's $(3,4)$ fibration with $m=3\psi(a_0)$, $n=4\psi(a_1)$: $D=12\psi(a_0+a_1)=p$, and $|p|=1$ makes $\pi_1$ trivial and $d_2(12\psi)=p\,\omega$ an isomorphism.
\end{calculation}
\begin{status}Calculation (exact; Smith normal forms). The six-dimensional representation is an algebraic quantum sector only, not a vertex algebra, modular functor, or QFT.\end{status}
\begin{conjecture}[Integral affine transgression]
For an oriented Seifert circle quotient over $S^2$ with two multiple fibres of local invariants $(r,m)$, $(s,n)$ (rotations adding), $d_2(rs\psi)=D(r,s;m,n)\,\omega$ in the Leray spectral sequence, equivalently $e=m/r+n/s=D/rs$.
\end{conjecture}
\begin{status}Conjecture (precise; evidence: the Engel $(3,4)$ case; a proof needs the constructible-sheaf carrier of $\psi$, effective local hypotheses, orientations, and a section normalization; when $\gcd(r,s)>1$ the multiple must be $\operatorname{lcm}(r,s)$).\end{status}

\section{Local Gibbs states, Tate integrals, and fidelity}\label{sec:gibbs}

\begin{theorem}[Tate--sieve vector]
For $\phi_{p,\tau}=\mathbf 1_{\Z_p^\times}+p^{-\tau}\mathbf 1_{p\Z_p}$: $Z_p(\phi_{p,\tau},s)=\int_{\Q_p^\times}\phi_{p,\tau}|x|^s_pd^\times x=1+\frac{p^{-s-\tau}}{1-p^{-s}}$, so $\prod_{p\in S}Z_p=\sum_{p|n\Rightarrow p\in S}n^{-s}\operatorname{rad}(n)^{-\tau}$; $Z_p(\hat\phi_{p,\tau},1-s)=\gamma_p(s)Z_p(\phi_{p,\tau},s)$ with $\gamma_p(s)=\frac{1-p^{-s}}{1-p^{s-1}}$ independent of $\tau$; $\hat\phi_{p,\tau}=e_0+(p^{-\tau}-1)p^{-1}e_{-1}$ (self-dual iff $\tau=0$), and with $E_p,O_p$ the Fourier-even/odd parts $\hat\phi-\phi=\tau(\log p)O_p+O(\tau^2)$. The Fourier transform and shift on the lattice line $\mathcal R_p=\operatorname{span}\{f_k=\mathbf 1_{p^k\Z_p}\}$ satisfy $\mathcal F^2=1$, $\mathcal FU\mathcal F=U^{-1}$ (a $D_\infty$-representation), and $\mathcal R_p$ is the smallest Fourier- and shift-stable space containing $\phi_{p,\tau}$, $\tau\ne0$. The family $(\phi_{p,\tau})_p$, $\tau\ne0$, is not a pure tensor in the restricted tensor product with basic vectors $\mathbf 1_{\Z_p}$.
\end{theorem}
\begin{status}Theorem (classical; Tate's thesis \cite{Tate1950}; $\hat e_k=p^{-k}e_{-k}$).\end{status}

\begin{proposition}[Critical Gibbs--deletion duality and local scattering]
Let $d\nu_{p;s,\tau}\propto|x|_p^{s-1}\phi_{p,\tau}(x)dx$ on $\Z_p$. Its residue pushforward is uniform at $\tau=0$ iff $s=1$; at $s=1$, $\pi_{p,\tau}(0)=\frac{p^{-\tau}}{p-1+p^{-\tau}}$, $\pi_{p,\tau}(r)=\frac1{p-1+p^{-\tau}}$ $(r\ne0)$. With $q_{p,\tau}=(p-1)\pi_{p,\tau}$ and $\mu_{p,\tau}=1-q_{p,\tau}$: $\mu_{p,\tau}$ is a probability law, $\mu(0)=1-\beta_p$, $\mu(r)=\beta_p/(p-1)$, $\beta_p=\frac{(p-1)p^{-\tau}}{p-1+p^{-\tau}}$, $B_p=\frac{p-1}{p-1+p^{-\tau}}=Z_p(1,\tau)^{-1}$, $\beta_p/B_p=p^{-\tau}$; it is the unique profile constant on $\F_p^\times$ with mean survival $(p-1)/p$ and ratio $p^{-\tau}$. Every nontrivial additive character is an eigenvector of the convolution operators with $r_p(\tau)=\frac{p^{-\tau}-1}{p-1+p^{-\tau}}$ (for $C_\pi$) and $\delta_p(\tau)=-(p-1)r_p(\tau)$ (for $C_\mu$), so $C_\mu+(p-1)C_\pi=pP_0$, $C_\mu$ is positive Markov for $\tau\ge0$ while $C_\pi$ is not positive for $\tau>0$; the algebra generated by $\{C_{\pi_{p,\tau}}\}$ is $\C P_0\oplus\C(1-P_0)$, and over a finite $S$ the eigenvalue of $\bigotimes_pC_{\pi_{p,\tau}}$ on a character $\chi$ is $\prod_{p\in\operatorname{supp}\chi}r_p(\tau)=(-\tau)^{|\operatorname{supp}\chi|}\prod\frac{\log p}p+O(\tau^{k+1})$, a $2^{|S|}$-dimensional Boolean algebra.
\end{proposition}
\begin{status}Proposition (proved here; finite Fourier analysis on $\F_p$).\end{status}

\begin{calculation}[Universal critical fidelity curve]
Let $\Omega_x=\bigotimes_{p\le x}\mathbf 1_{\Z_p}$ and $\Psi_{x,\tau}=\bigotimes_{p\le x}\psi_{p,\tau}$ (normalized $\phi_{p,\tau}$). For fixed $\tau>0$, $\langle\Omega_x,\Psi_{x,\tau}\rangle=C_\tau(\log x)^{-1/2}(1+o(1))\to0$. For $\tau_x=t/\log x$,
\[
\lim_{x\to\infty}\langle\Omega_x,\Psi_{x,\tau_x}\rangle=\mathfrak F(t)=\exp\!\big[-\tfrac12I(t)\big],\quad I(t)=\int_0^1\frac{(1-e^{-tu})^2}u\,du=\gamma+\log t-\log2+2E_1(t)-E_1(2t),
\]
$I(t)=\tfrac{t^2}2-\tfrac{t^3}3+\tfrac{7t^4}{48}+O(t^5)$, $I(t)=\log t+\gamma-\log2+o(1)$; $\mathfrak F(t)=1-\tfrac{t^2}4+O(t^3)$, $\mathfrak F(t)\sim e^{-(\gamma-\log2)/2}t^{-1/2}$.
\end{calculation}
\begin{status}Calculation (exact; local fidelity $-\log\frac{p-1+a}{\sqrt{p(p-1+a^2)}}=\frac{(1-a)^2}{2p}+O(p^{-2})$ and the prime-scale Riemann sum $\sum_{p\le x}f(\log p/\log x)/p\to\int_0^1f(u)du/u$ for $f(u)=O(u^\alpha)$, a consequence of Mertens' theorem).\end{status}

\begin{calculation}[Two-source partition functions]
$Z_S(s,\tau)=\operatorname{Tr}e^{-sH_{\mathrm{val}}-\tau H_{\mathrm{supp}}}=\prod_{p\in S}(1+\frac{p^{-s-\tau}}{1-p^{-s}})$, with $-\partial_s\log Z=\langle H_{\mathrm{val}}\rangle=\sum_p\frac{\log p}{p^s-1}$ (the valuation current, $=-\zeta'/\zeta$ in the limit), $-\partial_\tau\log Z=\langle H_{\mathrm{supp}}\rangle=\sum_p(\log p)p^{-s}$ (primitive primes only), $\langle H_{\mathrm{jet}}\rangle=\sum_p\sum_{m\ge2}(\log p)p^{-ms}$; local covariances at $\tau=0$, $q=p^{-s}$: $\operatorname{Var}N_p=q/(1-q)^2$, $\operatorname{Var}P_p=q(1-q)$, $\operatorname{Cov}=q$. Squarefree Koszul model: $H^0(K_S)=B_S/(x_p^2)$, $\chi=\prod(1+p^{-s-\tau})$; binary shells $k[x]\cong\bigotimes_jk[\epsilon_j]/(\epsilon_j^2)$, $\deg\epsilon_j=2^j$, give $\zeta(s)=\prod_{j\ge0}\zeta(2^js)/\zeta(2^{j+1}s)$; squarefree series $\zeta(s)/\zeta(2s)$ has log-derivative coefficients $(-1)^{m-1}\log p$ (even multiple-cover coefficients change sign); the gcd cocycle $c_\tau(m,n)=\operatorname{rad}(\gcd(m,n))^\tau=\delta W_\tau$ is a coboundary, so the twisted semigroup algebra is untwisted; the two-variable divisor zeta $\mathcal Z_X(T,u)=\sum_DT^{\deg D}u^{\deg D_{\mathrm{red}}}=\prod_x(1+\frac{(uT)^{\deg x}}{1-T^{\deg x}})$. For any analytic germ $g$, $F(\tau)=-\log\tau+g(\tau)$ has $F''>0$ for small $\tau>0$.
\end{calculation}
\begin{status}Calculation (exact; Euler products and Fock traces). The explicit formula is a valuation-current trace, not a support trace.\end{status}

