\subsection{The level-six fibre lattice in Engel's torus fibration \cite{P5}}

\begin{theorem}[1.1, 2.2, 3.1, 4.1 of \cite{P5}]\label{thm:P5-engel}
Let $f\colon Y(u)\to\mathbb P^1$ be Engel's fibration \cite{Engel2026}, $F$ a smooth
fibre, $\Lambda=H_1(F,\Z)$ with the monodromies $T_0,T_1$ of order $3,4$ around $0,1$.
\begin{enumerate}
\item $\Lambda^\Gamma=\Z\delta_0$ (the circle class of the principal $\mathbb G_m$-bundle),
$V^\Gamma=\Z\psi$, and $(\Lambda^2V)^\Gamma=\Z\xi$ with $\iota_{\delta_0}\xi=-6\psi$; in a
unimodular basis $[\xi]=J\oplus6J$, Smith form $\mathrm{diag}(1,1,6,6)$, discriminant group
$(\Z/6)^2$. The sign of $-6$ is tensorial in the orientations of $\delta_0$, $\psi$ and
the contraction.
\item The discriminant module carries a perfect alternating pairing with value $\tfrac16$
on the generators, and the Heisenberg group $H_6=\mu_6\times K\times\widehat K$ acts
irreducibly on the six-dimensional $\C[K]$ with $\mu_6$ tautological.
\item For the two-multiple-fibre group $G_{b_0}=\langle c,x_0,x_1\mid c\text{ central},
x_0x_1=c^{b_0},x_0^r=c^m,x_1^s=c^n\rangle$ with $\Delta=rn+sm-rsb_0$ and
$d=\gcd(r,s,m,n)$: $G_{b_0}\cong\Z/d\oplus\Z/(|\Delta|/d)$ if $\Delta\ne0$, and
$\Z\oplus\Z/d$ if $\Delta=0$; for a Seifert manifold $rs\,e(M)=\Delta$.
\item In the Leray spectral sequence of $f$, with $p=4m+3n$ the transgression coefficient
of Engel's multiplicities $(3,4)$, $d_2^{0,1}(12\psi)=p\,\omega$, and
$\pi_1(Y(u))\cong\Z/|p|$; no transgression formula for other multiplicities is asserted,
and for $(2,2;1,1;0)$ the naive transport of $rn+sm$ fails ($-2\ne-4$).
\end{enumerate}
\end{theorem}

Nothing here concerns complex structures on $S^6$: when $Y(u)\cong S^6$ the lattice
$\Lambda$ is auxiliary and all intermediate cohomology of the total space vanishes.

